import { CodexContentType } from '../domain/codex.js';
import { AttachmentKind } from '@protocol';
import { type PreparedAttachment } from './types.js';

/** Paths are generated by the daemon. Names never become terminal instructions. */
export function attachmentPrompt(text: string, attachments: readonly PreparedAttachment[]): string {
  if (!attachments.length) {
    return text;
  }

  const references = attachments.map(({ path }) => `Attached local file: ${JSON.stringify(path)}`).join('\n');

  return text ? `${text}\n\n${references}` : references;
}

export function codexAttachmentInput(text: string, attachments: readonly PreparedAttachment[]) {
  const files = attachments.filter((item) => item.descriptor.kind === AttachmentKind.File);
  const prompt = attachmentPrompt(text, files);

  return [
    ...(prompt ? [{ type: CodexContentType.Text, text: prompt }] : []),
    ...attachments
      .filter((item) => item.descriptor.kind === AttachmentKind.Image)
      .map(({ path }) => ({ type: CodexContentType.LocalImage, path })),
  ];
}
